?><style>*{box-sizing:border-box}.container{max-width:1200px;margin:30px auto;padding:0 16px}.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px;align-items:start}.tool-main,.tool-sidebar{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:25px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.upload{border:2px dashed #d6dbea;border-radius:15px;padding:42px 20px;text-align:center;cursor:pointer;margin:20px 0}.btn{border:0;border-radius:10px;padding:12px 18px;background:#635bff;color:#fff;font-weight:800;cursor:pointer}.result{margin-top:16px;padding:15px;background:#f7f8fb;border:1px solid #e5e9f0;border-radius:12px}@media(max-width:800px){.tool-layout{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}}</style><main class="container"><div class="tool-layout"><section class="tool-main"><h1>PDF to PNG</h1><p>Convert every PDF page into a high-quality PNG image in your browser.</p><input id="file" type="file" accept="application/pdf" hidden><div class="upload" id="upload"><strong>📄 Drop your PDF here</strong><br>or click to choose a PDF</div><button class="btn" id="convert" disabled>Convert to PNG</button><div class="result" id="result">No PDF selected.</div></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script>const file=document.getElementById('file'),upload=document.getElementById('upload'),convert=document.getElementById('convert'),result=document.getElementById('result');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';upload.onclick=()=>file.click();file.onchange=()=>{if(file.files[0]){convert.disabled=false;result.textContent=file.files[0].name+' selected.'}};convert.onclick=async()=>{const f=file.files[0];if(!f)return;convert.disabled=true;result.textContent='Converting…';try{const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),v=p.getViewport({scale:2}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;await new Promise(resolve=>c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='page-'+i+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);resolve()},'image/png'))}result.textContent=pdf.numPages+' page(s) converted to PNG.'}catch(e){console.error(e);result.textContent='Could not convert this PDF.'}finally{convert.disabled=false}}</script><?php require_once __DIR__ . '/../footer.php'; ?>